// A circuit breaker for one backend service: closed under normal operation,
// open and failing fast after repeated failures, and half-open to cautiously
// test recovery after a cooldown period.
class CircuitBreaker {
    private enum State { CLOSED, OPEN, HALF_OPEN }

    private State state = State.CLOSED;
    private int failureCount = 0;
    private long openedAt = -1;
    private int halfOpenTrialsUsed = 0;

    private final int failureThreshold;
    private final long cooldownMillis;
    private final int halfOpenTrialsAllowed;

    CircuitBreaker(int failureThreshold, long cooldownMillis, int halfOpenTrialsAllowed) {
        this.failureThreshold = failureThreshold;
        this.cooldownMillis = cooldownMillis;
        this.halfOpenTrialsAllowed = halfOpenTrialsAllowed;
    }

    // Returns whether a request destined for this backend should be forwarded
    // right now, transitioning from open to half-open once the cooldown has elapsed.
    boolean allowRequest(long now) {
        if (state == State.OPEN) {
            if (now - openedAt >= cooldownMillis) {
                state = State.HALF_OPEN; // cooldown elapsed: cautiously start testing recovery
                halfOpenTrialsUsed = 0;
            } else {
                return false; // still cooling down: fail fast, never forwarded
            }
        }

        if (state == State.HALF_OPEN) {
            if (halfOpenTrialsUsed >= halfOpenTrialsAllowed) {
                return false; // already used up this window's trial allowance
            }
            halfOpenTrialsUsed++;
            return true; // this is a trial request
        }

        return true; // CLOSED: forward normally
    }

    // Call after a forwarded request actually succeeds.
    void recordSuccess() {
        if (state == State.HALF_OPEN) {
            state = State.CLOSED; // the trial succeeded: genuine recovery confirmed
        }
        failureCount = 0; // any success resets the failure count
    }

    // Call after a forwarded request actually fails.
    void recordFailure(long now) {
        if (state == State.HALF_OPEN) {
            state = State.OPEN; // the trial failed: still broken, reopen for another full cooldown
            openedAt = now;
            return;
        }
        failureCount++;
        if (failureCount >= failureThreshold) {
            state = State.OPEN; // too many consecutive failures: trip the circuit open
            openedAt = now;
        }
    }

    String state() {
        return state.name();
    }
}

