// A circuit breaker for one backend service: closed under normal operation,
// open and failing fast after repeated failures, and half-open to cautiously
// test recovery after a cooldown period.
class CircuitBreaker {
public:
    enum State { CLOSED, OPEN, HALF_OPEN };

    CircuitBreaker(int failureThreshold, long cooldownMillis, int halfOpenTrialsAllowed)
        : state(CLOSED), failureCount(0), openedAt(-1), halfOpenTrialsUsed(0),
          failureThreshold(failureThreshold), cooldownMillis(cooldownMillis),
          halfOpenTrialsAllowed(halfOpenTrialsAllowed) {}

    bool allowRequest(long now) {
        if (state == OPEN) {
            if (now - openedAt >= cooldownMillis) {
                state = HALF_OPEN; // cooldown elapsed: cautiously start testing recovery
                halfOpenTrialsUsed = 0;
            } else {
                return false; // still cooling down: fail fast, never forwarded
            }
        }

        if (state == HALF_OPEN) {
            if (halfOpenTrialsUsed >= halfOpenTrialsAllowed) {
                return false; // already used up this window's trial allowance
            }
            halfOpenTrialsUsed++;
            return true; // this is a trial request
        }

        return true; // CLOSED: forward normally
    }

    void recordSuccess() {
        if (state == HALF_OPEN) {
            state = CLOSED; // the trial succeeded: genuine recovery confirmed
        }
        failureCount = 0; // any success resets the failure count
    }

    void recordFailure(long now) {
        if (state == HALF_OPEN) {
            state = OPEN; // the trial failed: still broken, reopen for another full cooldown
            openedAt = now;
            return;
        }
        failureCount++;
        if (failureCount >= failureThreshold) {
            state = OPEN; // too many consecutive failures: trip the circuit open
            openedAt = now;
        }
    }

    string stateName() {
        if (state == CLOSED) return "CLOSED";
        if (state == OPEN) return "OPEN";
        return "HALF_OPEN";
    }

private:
    State state;
    int failureCount;
    long openedAt;
    int halfOpenTrialsUsed;
    int failureThreshold;
    long cooldownMillis;
    int halfOpenTrialsAllowed;
};

int main() {
    // Scenario 1: the circuit opens after 3 failures, then recovers via a successful trial.
    CircuitBreaker breaker1(3, 5000, 1);
    breaker1.recordFailure(0);
    breaker1.recordFailure(100);
    breaker1.recordFailure(200); // 3rd consecutive failure: circuit should trip open here
    cout << "Breaker1 state after 3 failures: " << breaker1.stateName() << endl;

    cout << "Breaker1 allowRequest(300) while open, cooldown not yet elapsed: " << (breaker1.allowRequest(300) ? "true" : "false") << endl;

    bool trialAllowed = breaker1.allowRequest(5300); // cooldown (5000ms) has now elapsed since it opened at 200
    cout << "Breaker1 allowRequest(5300) after cooldown elapses (a trial): " << (trialAllowed ? "true" : "false") << endl;
    cout << "Breaker1 state during the trial: " << breaker1.stateName() << endl;

    breaker1.recordSuccess(); // the trial request succeeds
    cout << "Breaker1 state after a successful trial: " << breaker1.stateName() << endl;
    cout << "Breaker1 allowRequest(5400) now that it is closed again: " << (breaker1.allowRequest(5400) ? "true" : "false") << endl;

    // Scenario 2: the circuit opens the same way, but its half-open trial fails, reopening it.
    CircuitBreaker breaker2(3, 5000, 1);
    breaker2.recordFailure(0);
    breaker2.recordFailure(100);
    breaker2.recordFailure(200);
    cout << "Breaker2 state after 3 failures: " << breaker2.stateName() << endl;

    bool trialAllowed2 = breaker2.allowRequest(5300);
    cout << "Breaker2 allowRequest(5300), a trial: " << (trialAllowed2 ? "true" : "false") << endl;
    breaker2.recordFailure(5300); // the trial request fails
    cout << "Breaker2 state after a failed trial: " << breaker2.stateName() << endl;
    cout << "Breaker2 allowRequest(5400) immediately after reopening: " << (breaker2.allowRequest(5400) ? "true" : "false") << endl;

    return 0;
}

